local T = require "waf.types"

-- Shallow-merges one or more {key=validator} tables into a new table; later
-- tables' keys win on conflict.
local function merge(...)
  local out = {}
  for _, t in ipairs({...}) do
    for k, v in pairs(t) do out[k] = v end
  end
  return out
end

-- pairs() iteration order over a table's string-keyed hash part is not
-- guaranteed stable across separate Lua process starts. Below, several
-- loops fold many actions'/submodules' field tables into one flat union,
-- where a field name shared by two actions with different constraints
-- (e.g. 'filename') resolves to whichever one the loop visits last - so
-- an unordered pairs() there made the union's winner for such fields (and
-- therefore the offline test suite's generated case count) vary between
-- runs, confirmed by diffing two consecutive runs of the same generated
-- file. sorted_pairs() makes that resolution repeatable.
local function sorted_pairs(t)
  local keys = {}
  for k in pairs(t) do keys[#keys + 1] = k end
  table.sort(keys)
  local i = 0
  return function()
    i = i + 1
    if keys[i] ~= nil then return keys[i], t[keys[i]] end
  end
end

